    child: PythonClassDeclarationKnowledge,
    base: PythonClassBaseSyntax,
    bindings: tuple[_Binding, ...],
    source_imports: PythonImportDeclarationAnalysis,
    source_interpretations: tuple[PythonModuleInterpretation, ...],
